import{_ as t,o as e,c as o,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const d=JSON.parse('{"title":"保罗·黑曾","description":"","frontmatter":{"title":"保罗·黑曾","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/保罗·黑曾.md","filePath":"04_people/保罗·黑曾.md"}'),l={name:"04_people/保罗·黑曾.md"};function i(n,a,s,_,h,p){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="保罗·黑曾" tabindex="-1">保罗·黑曾 <a class="header-anchor" href="#保罗·黑曾" aria-label="Permalink to &quot;保罗·黑曾&quot;">​</a></h1><ul><li><strong>角色职位</strong>：富国银行（Wells Fargo）CEO</li><li><strong>与巴菲特关系</strong>：富国银行长期领导者，伯克希尔银行投资组合的核心管理者</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>保罗·黑曾是富国银行另一位重要的CEO，与前任卡尔·赖查特共同构成了富国银行崛起过程中的双子星。黑曾接任CEO后，延续了赖查特时代的稳健经营风格，继续深化富国银行的竞争优势。</p><p>在黑曾的领导下，富国银行逐步确立了&quot;社区银行+批发银行&quot;的商业模式，在全美范围内建立起差异化的竞争优势。该行以优秀的客户服务和高效的运营效率著称，盈利能力持续领先于同业。这种清晰的定位和执行力，与巴菲特一贯欣赏的&quot;能力圈&quot;投资哲学不谋而合。</p><p>巴菲特对富国银行的持有期长达数十年，这在巴菲特的投资生涯中极为罕见。黑曾的管理团队功不可没——他们以持续的优异表现为伯克希尔的这笔投资提供了坚实的支撑。巴菲特曾在股东信中多次提及富国银行，将其视为&quot;好行业+好管理层&quot;组合的典范。富国银行也为巴菲特的长期投资者带来了丰厚的回报。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1990年代</strong>：担任富国银行CEO，延续银行稳健增长轨迹</li><li><strong>2000年代</strong>：继续领导富国银行扩张，巩固其美国第四大银行地位</li><li><strong>持续至今</strong>：在黑曾及其团队的领导下，富国银行成为巴菲特持仓时间最长的银行股之一</li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该人物在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/search.html?q=保罗·黑曾在1990年股东信中的原话">1990年：完整翻译|/01_letters/1990年/翻译</a></li></ul>',11)])])}const c=t(l,[["render",i]]);export{d as __pageData,c as default};
